local KTool = CS.Engine.Lib.KTool
local FishingMgr = import('Game.UI.Fishing.FishingMgr')
local FishingUtils = import('Game.UI.Fishing.FishingUtils')

---@class DamageBarService
local DamageBarService = Class("DamageBarService")

function DamageBarService.new(from)
    local obj = DamageBarService.New()
    obj.luaDialog = from
    for k, v in pairs(from) do
        obj[k]=v
    end
    return obj
end

function DamageBarService:UpdateInfo()

end

function DamageBarService:ShowMe()

end

function DamageBarService:HideMe()

end

--刷新伤害信息
function DamageBarService:RefreshDamageInfo()
    local damage = checkInt(FishingMgr:GetInstance():GetCurDamage())
    local damageText = damage > 0 and "-"..damage or ""
    CfUtils.FillText(self.TextDropBlood, damageText)
    --CfUtils.PlayAnimator(self.TextDropBlood, "Play")

    KTool.SetActive(self.ImgHit, true)

    local force = FishingMgr:GetInstance():GetCurForce()
    local vo = FishingUtils.GetFishingPullPowerVoByForce(force)
    if vo then
        CfUtils.FillText(self.TxtNumber, vo.desc)
        KTool.SetActive(self.PerfectNode, checkNumber(vo.id) == 5)
        if checkNumber(vo.id) == 5 then
            CfUtils.PlayAnimator(self.PerfectNode, "Play")
        end
        KTool.SetActive(self.RingEffect, checkNumber(vo.id) == 5)
    end
end

return DamageBarService